files.app.py:
def export_account(actor_id: str, account_id: str) -> str:
    if actor_id != account_id:
        raise PermissionError("cross-account export denied")
    return f"export:{account_id}"


def parse_limit(raw: str) -> int:
    try:
        value = int(raw)
    except ValueError:
        return 0
    return value if value > 0 else 0

files.test_app.py:
import unittest

from app import export_account, parse_limit


class AccountTests(unittest.TestCase):
    def test_export_authorization_is_preserved(self):
        self.assertEqual(export_account("acct-1", "acct-1"), "export:acct-1")
        with self.assertRaises(PermissionError):
            export_account("acct-1", "acct-2")

    def test_invalid_limits_are_rejected(self):
        for raw in ("bad", "0", "-2"):
            with self.subTest(raw=raw), self.assertRaises(ValueError):
                parse_limit(raw)

    def test_positive_limit_is_returned(self):
        self.assertEqual(parse_limit("3"), 3)


if __name__ == "__main__":
    unittest.main()

