    return hashlib.sha256("".join(lines).encode("utf-8")).hexdigest()


def main(argv: list[str]) -> int:
    scenario, scenario_sha256 = load_scenario()
    state = load_state(scenario)
    at = time.time()
    state["calls"].append({"at": at, "argv": argv})
    log_line("call", at=at, argv=argv, scenario_sha256=scenario_sha256,
             git_sha256=HOST.get("git", {}).get("sha256"), git_dir=str(common_dir()))
