def dedupe_key(event):
    return str(event["id"])


def deliver_once(events, seen=None):
    seen = set() if seen is None else seen
    delivered = []
    for event in events:
        key = dedupe_key(event)
        if key not in seen:
            seen.add(key)
            delivered.append(event)
    return delivered

