    head = facts.head(state["head_branch"])
    record = state["heads"].setdefault(head, {"polls": 0})
    record["polls"] += 1
    facts.polled(head, record["polls"])
    rows = []
    for index, check in enumerate(scenario["checks"]):
        run_id = RUN_BASE + index
        link = f"{scenario['repo_url']}/actions/runs/{run_id}/job/{run_id + JOB_OFFSET}"
        state_name, elapsed, note, _ = check_result(scenario, facts, index, head,
                                                    record["polls"])
        rows.append({"name": check["name"], "state": state_name,
                     "elapsed": elapsed, "link": link, "note": note,
                     "required": check.get("required", True)})
    return rows


