        raise Stop("X Pull request is not mergeable: the base branch policy prohibits the merge.")
    if "--merge" not in argv:
        raise Stop("X Merge method not allowed: this repository accepts merge commits only (--merge).")
    if facts.merged(state["head_branch"], base):
        raise Stop("X Pull request is already merged")
