import os
import subprocess
import sys
import tempfile
import time
from pathlib import Path

TOOLS = Path(__file__).resolve().parent
ROOT = TOOLS.parent
LOG_PREFIX = "gh-stand-in-log "
INVOCATION = os.urandom(6).hex()
RUN_BASE, JOB_OFFSET, ELAPSED = 5100, 70, "1m04s"
WINDOWS_SHIM = (
    "import ntpath, os, sys, unittest\n"
    "sys.path.insert(0, 'src')\n"
    "suite = unittest.defaultTestLoader.discover('tests')\n"
    "os.path = ntpath\n"
    "os.sep = ntpath.sep\n"
    "result = unittest.TextTestRunner(verbosity=2).run(suite)\n"
    "sys.exit(0 if result.wasSuccessful() else 1)\n"
)
PLAIN_RUN = (
    "import sys, unittest\n"
    "sys.path.insert(0, 'src')\n"
    "suite = unittest.defaultTestLoader.discover('tests')\n"
    "result = unittest.TextTestRunner(verbosity=2).run(suite)\n"
    "sys.exit(0 if result.wasSuccessful() else 1)\n"
)
JSON_FIELDS = ("url", "state", "isDraft", "baseRefName", "headRefName",
               "reviewDecision", "title", "number")


class Stop(Exception):
    """An error answer: the message goes to stderr and the exit status is 1."""


# The answer: a pure function of the arguments, the stand-in state, the
# scenario and the repository facts it asks for.

def initial_state(scenario: dict) -> dict:
    return {"heads": {}, "created": bool(scenario.get("open", False)),
            "draft": bool(scenario.get("draft", False)),
            "head_branch": scenario.get("head")}


def base_name(scenario: dict) -> str:
    return scenario.get("base", "main")


def check_result(scenario: dict, facts, index: int, head: str,
                 polls: int) -> tuple[str, str, str, str | None]:
    """State, elapsed, note and job log of one check at a head after some polls."""
    check = scenario["checks"][index]
    mode = check["mode"]
    if polls <= scenario.get("pending_polls", 0) or mode == "queued":
        note = "Waiting for a runner to pick up this job"
        if mode == "queued":
            note = check.get("note", note)
        return "pending", "0", note, None
    if mode == "not_started":
        return "fail", "0", check["note"], check["note"]
    if mode in {"tests", "tests_windows"}:
        ok, output = facts.tests(head, index, mode)
        return ("pass" if ok else "fail"), ELAPSED, "", output
    return "pass", ELAPSED, "", None


def evaluate(scenario: dict, state: dict, facts) -> list[dict]:
    head = facts.head(state["head_branch"])
    record = state["heads"].setdefault(head, {"polls": 0})
    record["polls"] += 1
    facts.polled(head, record["polls"])
    rows = []
    for index, check in enumerate(scenario["checks"]):
        run_id = RUN_BASE + index
        link = f"{scenario['repo_url']}/actions/runs/{run_id}/job/{run_id + JOB_OFFSET}"
        state_name, elapsed, note, _ = check_result(scenario, facts, index, head,
                                                    record["polls"])
        rows.append({"name": check["name"], "state": state_name,
                     "elapsed": elapsed, "link": link, "note": note,
                     "required": check.get("required", True)})
    return rows


def view(scenario: dict, state: dict, facts) -> dict:
    merged = facts.merged(state["head_branch"], base_name(scenario))
    return {
        "url": scenario["pr_url"],
        "state": "MERGED" if merged else "OPEN",
        "isDraft": state["draft"],
        "baseRefName": base_name(scenario),
        "headRefName": state["head_branch"],
        "reviewDecision": scenario.get("review_decision", ""),
        "title": scenario["title"],
        "number": int(scenario["pr_url"].rsplit("/", 1)[1]),
    }


def respond(argv: list[str], state: dict, scenario: dict, facts, io) -> int:
    try:
        return dispatch(argv, state, scenario, facts, io)
    except Stop as stop:
        io.err(str(stop))
        return 1


def dispatch(argv: list[str], state: dict, scenario: dict, facts, io) -> int:
    base = base_name(scenario)
    if argv[:2] == ["pr", "create"]:
        if state["created"]:
            io.err(f"a pull request for branch \"{state['head_branch']}\" into branch "
                   f"\"{base}\" already exists:\n{scenario['pr_url']}")
            return 1
        if "--base" in argv[:-1] and argv[argv.index("--base") + 1] != base:
            raise Stop(f"this sandbox only has a pull request target of {base}")
        state["created"] = True
        state["draft"] = "--draft" in argv
        state["head_branch"] = facts.branch()
        io.out(scenario["pr_url"])
        return 0
    if argv[:2] not in (["pr", "view"], ["pr", "ready"], ["pr", "checks"],
                        ["run", "view"], ["run", "rerun"], ["pr", "merge"]):
        raise Stop("unsupported in this offline stand-in: " + " ".join(argv))
    if not state["created"]:
        raise Stop(f"no pull requests found for branch \"{facts.branch()}\"")
    if argv[:2] == ["pr", "view"]:
        data = view(scenario, state, facts)
        if "--json" in argv[:-1]:
            fields = argv[argv.index("--json") + 1].split(",")
            io.out(json.dumps({key: data[key] for key in fields if key in JSON_FIELDS}))
        else:
            io.out(f"{data['title']}\nstate: {data['state']}\ndraft: {data['isDraft']}\n"
                   f"base: {data['baseRefName']}\nreview: {data['reviewDecision']}\n"
                   f"url: {data['url']}")
        return 0
    if argv[:2] == ["pr", "ready"]:
        state["draft"] = "--undo" in argv
        io.out("draft" if state["draft"] else "ready for review")
        return 0
    if argv[:2] == ["pr", "checks"]:
        watch = "--watch" in argv
        interval = 10
        for flag in ("--interval", "-i"):
            if flag in argv[:-1]:
                value = argv[argv.index(flag) + 1]
                if not value.isdigit():
                    raise Stop(f"invalid argument \"{value}\" for \"--interval\" flag")
                if not watch:
                    raise Stop("cannot use `--interval` flag without `--watch` flag")
                interval = max(1, int(value))
                break
        while True:
            rows = evaluate(scenario, state, facts)
            facts.save(state)
            if "--required" in argv:
                rows = [row for row in rows if row["required"]]
            for row in rows:
                io.out("\t".join([row["name"], row["state"], row["elapsed"],
                                  row["link"], row["note"]]))
            states = {row["state"] for row in rows}
            if watch and "pending" in states and facts.keep_watching(interval, state):
                continue
            if "fail" in states:
                return 1
            return 8 if "pending" in states else 0
    if argv[:2] == ["run", "view"]:
        run_id = next((arg for arg in argv[2:] if arg.isdigit()), "")
        head = facts.head(state["head_branch"])
        index = int(run_id) - RUN_BASE if run_id else -1
        polls = state["heads"].get(head, {}).get("polls", 0)
        if polls and 0 <= index < len(scenario["checks"]):
            log = check_result(scenario, facts, index, head, polls)[3]
            if log is not None:
                io.out(log)
                return 0
        raise Stop(f"failed to get run log: log not found for run {run_id}")
    if argv[:2] == ["run", "rerun"]:
        run_id = next((arg for arg in argv[2:] if arg.isdigit()), "")
        io.out(f"Requested rerun of run {run_id}")
        return 0
    if scenario.get("merge") != "allowed":
        raise Stop("X Pull request is not mergeable: the base branch policy prohibits the merge.")
    if "--merge" not in argv:
        raise Stop("X Merge method not allowed: this repository accepts merge commits only (--merge).")
    if facts.merged(state["head_branch"], base):
        raise Stop("X Pull request is already merged")
    number = int(scenario["pr_url"].rsplit("/", 1)[1])
    message = f"Merge pull request #{number} from {state['head_branch']}"
    if facts.merge(state["head_branch"], base, message) is None:
        raise Stop("X Pull request is not mergeable: the merge has conflicts "
                   "(this stand-in needs git 2.38 or newer)")
    io.out(f"Merged pull request #{number} ({scenario['title']}) into {base}")
    return 0


# The live host: this checkout, the clock and the log in the git dir.
# Git is the executable the harness pinned before the trial, called by path
# and checked by digest before each use. It runs with a fixed PATH, only
# home, locale and identity variables (no other GIT_ setting and no loader
# variable), and no replacement objects. A commit's files and ancestry are
# read from objects whose bytes match their names, so replacement refs,
# grafts, shallow files, commit-graph files and attributes cannot change
# what a SHA denotes.

HOST: dict = {}
GIT_ENV_KEEP = {"HOME", "USER", "LOGNAME", "TMPDIR", "LANG", "LC_ALL", "LC_CTYPE", "TZ",
                "GIT_AUTHOR_NAME", "GIT_AUTHOR_EMAIL", "GIT_AUTHOR_DATE",
                "GIT_COMMITTER_NAME", "GIT_COMMITTER_EMAIL", "GIT_COMMITTER_DATE"}


def git_run(*args: str, check: bool = True, text: bool = True) -> subprocess.CompletedProcess:
    git = HOST["git"]
    if hashlib.sha256(Path(git["path"]).read_bytes()).hexdigest() != git["sha256"]:
        raise RuntimeError(f"{git['path']} is not the git executable the harness pinned")
    env = {key: value for key, value in os.environ.items() if key in GIT_ENV_KEEP}
    env.update(PATH="/usr/bin:/bin", GIT_NO_REPLACE_OBJECTS="1")
    return subprocess.run([git["path"], "--no-replace-objects", *args], cwd=ROOT, env=env,
                          check=check, capture_output=True, text=text)


def git(*args: str) -> str:
    return git_run(*args).stdout.strip()


def git_object(oid: str, kind: str) -> bytes:
    """An object's bytes, checked against its name."""
    data = git_run("cat-file", kind, oid, text=False).stdout
    algorithm = "sha1" if len(oid) == 40 else "sha256"
    name = hashlib.new(algorithm, f"{kind} {len(data)}\0".encode() + data)
    if name.hexdigest() != oid:
        raise RuntimeError(f"git object {oid} does not match its name")
    return data


def commit_fields(oid: str, field: str) -> list[str]:
    header = git_object(oid, "commit").split(b"\n\n", 1)[0].decode("utf-8", "replace")
    return [line.split()[1] for line in header.splitlines()
            if line.startswith(field + " ")]


def is_ancestor(old: str, new: str) -> bool:
    seen, todo = set(), [new]
    while todo:
        oid = todo.pop()
        if oid == old:
            return True
        if oid not in seen:
            seen.add(oid)
            todo += commit_fields(oid, "parent")
    return False


def write_tree(oid: str, target: Path) -> None:
    """Write a tree's files as stored, without attributes or filters."""
    data, size, at = git_object(oid, "tree"), len(oid) // 2, 0
    while at < len(data):
        space, end = data.index(b" ", at), data.index(b"\0", at)
        mode, name = data[at:space], os.fsdecode(data[space + 1:end])
        child, at = data[end + 1:end + 1 + size].hex(), end + 1 + size
        if name in {"", ".", ".."} or "/" in name:
            raise RuntimeError(f"unsafe name in git tree {oid}: {name!r}")
        path = target / name
        if mode == b"40000":
            path.mkdir()
            write_tree(child, path)
        elif mode == b"120000":
            os.symlink(os.fsdecode(git_object(child, "blob")), path)
        elif mode == b"160000":
            path.mkdir()
        else:
            path.write_bytes(git_object(child, "blob"))
            if mode == b"100755":
                path.chmod(0o755)


def common_dir() -> Path:
    """The git common directory, read from the checkout without running git."""
    dot = ROOT / ".git"
    if dot.is_dir():
        return dot.resolve()
    gitdir = (ROOT / dot.read_text(encoding="utf-8").strip().removeprefix("gitdir:").strip())
    common = gitdir / "commondir"
    if common.is_file():
        return (gitdir / common.read_text(encoding="utf-8").strip()).resolve()
    return gitdir.resolve()


def log_line(event: str, **fields) -> None:
    """One evidence line per call, poll and result, on stderr."""
    record = {"event": event, "id": INVOCATION, **fields}
    print(LOG_PREFIX + json.dumps(record, sort_keys=True), file=sys.stderr, flush=True)


def load_scenario() -> tuple[dict, str]:
    """Read the pull request's hosted state and the pinned git from the host copy."""
    try:
        pointer = json.loads((common_dir() / "stand-in-host.json").read_text(encoding="utf-8"))
        raw = (Path(pointer["dir"]) / "tools/gh-scenario.json").read_bytes()
        HOST.update(json.loads((Path(pointer["dir"]) / "pins.json").read_text(encoding="utf-8")))
    except (OSError, ValueError, KeyError, TypeError):
        sys.exit("the stand-in host is not configured for this checkout")
    return json.loads(raw), hashlib.sha256(raw).hexdigest()


def state_path() -> Path:
    return common_dir() / "gh-stand-in.json"


def load_state(scenario: dict) -> dict:
    path = state_path()
    if path.is_file():
        return json.loads(path.read_text(encoding="utf-8"))
    return {"calls": [], "polls": [], **initial_state(scenario)}


def save_state(state: dict) -> None:
    state_path().write_text(json.dumps(state, indent=2) + "\n", encoding="utf-8")


def run_head(head: str, program: str, runner_dir: str) -> tuple[bool, str]:
    with tempfile.TemporaryDirectory() as work:
        write_tree(commit_fields(head, "tree")[0], Path(work))
        done = subprocess.run(
            [sys.executable, "-I", "-c", program], cwd=work, capture_output=True,
            text=True, env={"PATH": os.environ.get("PATH", "")},
        )
        output = (done.stdout + done.stderr).strip()
        for local in sorted({os.path.realpath(work), work}, key=len, reverse=True):
            output = output.replace(local, runner_dir)
    return done.returncode == 0, output


class Host:
    """Answers from this checkout; each fact is recorded with its query."""

    def __init__(self, scenario: dict, state: dict):
        self.scenario, self.state, self.facts = scenario, state, []

    def branch(self) -> str:
        value = git("branch", "--show-current")
        self.facts.append(["branch", value])
        return value

    def head(self, branch: str) -> str:
        value = git("rev-parse", "refs/heads/" + branch)
        self.facts.append(["head", branch, value])
        return value

    def merged(self, branch: str, base: str) -> bool:
        tips = [git_run("rev-parse", "--verify", "-q", "refs/heads/" + name,
                        check=False).stdout.strip() for name in (branch, base)]
        value = all(tips) and is_ancestor(*tips)
        self.facts.append(["merged", branch, base, value])
        return value

    def tests(self, head: str, index: int, mode: str) -> tuple[bool, str]:
        repo = self.scenario["repo_url"].rsplit("/", 1)[1]
        if mode == "tests_windows":
            ok, output = run_head(head, WINDOWS_SHIM, "D:\\a\\" + repo)
        else:
            ok, output = run_head(head, PLAIN_RUN, "/home/runner/work/" + repo)
        self.facts.append(["tests", head, index, mode, ok, output])
        return ok, output

    def merge(self, branch: str, base: str, message: str) -> str | None:
        base_ref = "refs/heads/" + base
        old, head = git("rev-parse", base_ref), git("rev-parse", "refs/heads/" + branch)
        done = git_run("merge-tree", "--write-tree", old, head, check=False)
        commit = None
        if done.returncode == 0:
            tree = done.stdout.splitlines()[0]
            commit = git("commit-tree", tree, "-p", old, "-p", head, "-m", message)
            git("-c", "core.hooksPath=/dev/null", "update-ref", base_ref, commit, old)
        self.facts.append(["merge", branch, base, message, commit])
        return commit

    def polled(self, head: str, count: int) -> None:
        at = time.time()
        self.state["polls"].append({"at": at, "head": head})
        log_line("poll", at=at, head=head, count=count)

    def save(self, state: dict) -> None:
        save_state(state)

    def keep_watching(self, interval: int, state: dict) -> bool:
        time.sleep(interval)
        fresh = load_state(self.scenario)
        state.clear()
        state.update(fresh)
        return True


class Streams:
    def __init__(self):
        self.stdout, self.stderr = [], []

    def out(self, text: str) -> None:
        print(text, flush=True)
        self.stdout.append(text + "\n")

    def err(self, text: str) -> None:
        print(text, file=sys.stderr, flush=True)
        self.stderr.append(text + "\n")


def digest(lines: list[str]) -> str:
    return hashlib.sha256("".join(lines).encode("utf-8")).hexdigest()


def main(argv: list[str]) -> int:
    scenario, scenario_sha256 = load_scenario()
    state = load_state(scenario)
    at = time.time()
    state["calls"].append({"at": at, "argv": argv})
    log_line("call", at=at, argv=argv, scenario_sha256=scenario_sha256,
             git_sha256=HOST.get("git", {}).get("sha256"), git_dir=str(common_dir()))
    save_state(state)
    host, io = Host(scenario, state), Streams()
    code, interrupted = 1, False
    try:
        code = respond(argv, state, scenario, host, io)
    except KeyboardInterrupt:
        code, interrupted = 130, True
    finally:
        save_state(state)
        log_line("result", at=time.time(), exit=code, interrupted=interrupted,
                 facts=host.facts, out=digest(io.stdout), err=digest(io.stderr))
    return code


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

