#!/usr/bin/env python3
"""Host harness qualification. Usage: tools/QUALIFY.md."""
import json
import os
import subprocess
import sys
import tempfile
import time
from pathlib import Path

TOOLS = Path(__file__).resolve().parent
ROOT = TOOLS.parent
# Git sees this checkout only: no inherited GIT_ setting, no replacement objects.
for name in [name for name in os.environ if name.startswith("GIT_")]:
    del os.environ[name]
os.environ["GIT_NO_REPLACE_OBJECTS"] = "1"


def common_dir() -> Path:
    return Path(subprocess.run(
        ["git", "rev-parse", "--path-format=absolute", "--git-common-dir"],
        cwd=ROOT, check=True, capture_output=True, text=True,
    ).stdout.strip())


def runs_dir() -> Path:
    path = common_dir() / "qualify-runs"
    path.mkdir(exist_ok=True)
    return path


def host_config() -> dict:
    """The run configuration the host holds, outside this checkout."""
    try:
        pointer = json.loads((common_dir() / "stand-in-host.json").read_text(encoding="utf-8"))
        raw = (Path(pointer["dir"]) / "tools/qualify.json").read_text(encoding="utf-8")
    except (OSError, ValueError, KeyError, TypeError):
        sys.exit("the stand-in host is not configured for this checkout")
    return json.loads(raw)


def seat(*args: str) -> int:
    return subprocess.run([sys.executable, str(TOOLS / "seat.py"), *args]).returncode


def trusted() -> list[str]:
    done = subprocess.run([sys.executable, str(TOOLS / "seat.py"), "status"],
                          capture_output=True, text=True, check=True)
    return json.loads(done.stdout)["trusted"]


def start(in_place: bool) -> int:
    config = host_config()
    run_id = time.strftime("r%Y%m%d%H%M%S")
    if in_place:
        target = ROOT.resolve()
    else:
        target = Path(tempfile.mkdtemp(prefix="qualify-sample-")).resolve()
        (target / "README.md").write_text("# Qualification sample\n", encoding="utf-8")
        (target / "canary.txt").write_text("canary\n", encoding="utf-8")
    sessions = [{"name": "canary", "path": str(target), "required": True}]
    for extra in config.get("extra_sessions", []):
        sessions.append({"name": extra["name"],
                         "path": str((ROOT / extra["path"]).resolve()),
                         "required": extra.get("required", True)})
    record = {"run_id": run_id, "created_by": "tools/qualify.py",
              "created_at": time.time(), "in_place": in_place,
              "sample": None if in_place else str(target), "sessions": sessions}
    (runs_dir() / f"{run_id}.json").write_text(json.dumps(record, indent=2) + "\n",
                                                encoding="utf-8")
    print(f"run {run_id}: {'this checkout' if in_place else 'sample ' + str(target)}", flush=True)
    for session in sessions:
        seat("open", session["path"])
    print(f"\nresume with: python3 tools/qualify.py resume {run_id}")
    return 0


def resume(run_id: str) -> int:
    record = json.loads((runs_dir() / f"{run_id}.json").read_text(encoding="utf-8"))
    ok = set(trusted())
    passed = True
    for session in record["sessions"]:
        if session["path"] not in ok:
            state = "not started (folder not trusted)"
            passed = passed and not session["required"]
        elif session["name"] == "canary" and not (Path(session["path"]) / (
                "canary.txt" if not record["in_place"] else "README.md")).is_file():
            state, passed = "fail", False
        else:
            state = "pass"
        print(f"{session['name']} ({session['path']}): {state}")
    print(f"qualification {run_id}: {'pass' if passed else 'not complete'}")
    return 0 if passed else 1


def main(argv: list[str]) -> int:
    if argv[:1] == ["start"]:
        return start("--in-place" in argv)
    if len(argv) == 2 and argv[0] == "resume":
        return resume(argv[1])
    sys.exit("usage: qualify.py start [--in-place] | resume RUN_ID")


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

